import{_ as p,r as n,o,c,e as a,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"响应和视图 - October CMS - 2.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"基本响应","slug":"基本响应","link":"#基本响应","children":[{"level":4,"title":"从 CMS 方法返回字符串","slug":"从-cms-方法返回字符串","link":"#从-cms-方法返回字符串","children":[]},{"level":4,"title":"从 AJAX 处理程序返回字符串","slug":"从-ajax-处理程序返回字符串","link":"#从-ajax-处理程序返回字符串","children":[]},{"level":4,"title":"从路由返回字符串","slug":"从路由返回字符串","link":"#从路由返回字符串","children":[]},{"level":4,"title":"创建自定义响应","slug":"创建自定义响应","link":"#创建自定义响应","children":[]},{"level":3,"title":"将标题附加到响应","slug":"将标题附加到响应","link":"#将标题附加到响应","children":[]},{"level":3,"title":"将 Cookie 附加到响应","slug":"将-cookie-附加到响应","link":"#将-cookie-附加到响应","children":[]}]},{"level":2,"title":"其他响应类型","slug":"其他响应类型","link":"#其他响应类型","children":[{"level":3,"title":"查看响应","slug":"查看响应","link":"#查看响应","children":[]},{"level":3,"title":"JSON 响应","slug":"json-响应","link":"#json-响应","children":[]},{"level":3,"title":"文件下载","slug":"文件下载","link":"#文件下载","children":[]}]},{"level":2,"title":"重定向","slug":"重定向","link":"#重定向","children":[{"level":3,"title":"使用闪存数据返回重定向","slug":"使用闪存数据返回重定向","link":"#使用闪存数据返回重定向","children":[{"level":4,"title":"重定向到上一个 URL","slug":"重定向到上一个-url","link":"#重定向到上一个-url","children":[]},{"level":4,"title":"重定向到当前页面","slug":"重定向到当前页面","link":"#重定向到当前页面","children":[]}]}]},{"level":2,"title":"响应宏","slug":"响应宏","link":"#响应宏","children":[]},{"level":2,"title":"视图","slug":"视图","link":"#视图","children":[{"level":4,"title":"将数据传递给视图","slug":"将数据传递给视图","link":"#将数据传递给视图","children":[]},{"level":4,"title":"将子视图传递给视图","slug":"将子视图传递给视图","link":"#将子视图传递给视图","children":[]},{"level":4,"title":"判断视图是否存在","slug":"判断视图是否存在","link":"#判断视图是否存在","children":[]}]}],"relativePath":"2.x/zh-cn/services/response-view.md","filePath":"2.x/zh-cn/services/response-view.md"}'),u={name:"2.x/zh-cn/services/response-view.md"};function r(k,s,g,d,h,v){const t=n("pre-heading"),e=n("post-heading");return o(),c("div",null,[a(t),s[0]||(s[0]=l("h1",null,"响应和视图",-1)),a(e),s[1]||(s[1]=i(`<h2 id="基本响应"><a href="#基本响应" class="header-anchor">#</a> 基本响应</h2><p>几乎可以从页面使用的 PHP 方法返回响应。这包括 <a href="./../cms/layouts.html#oc-dynamic-layouts">布局执行生命周期</a> 和 <a href="./../ajax/handlers.html">AJAX 处理程序定义</a>中包含的所有 CMS 方法.</p><h4 id="从-cms-方法返回字符串"><a href="#从-cms-方法返回字符串" class="header-anchor">#</a> 从 CMS 方法返回字符串</h4><p>从 CMS 页面、布局或组件方法返回字符串将在此时停止进程并覆盖默认行为，因此此处将显示&quot;Hello World&quot;字符串而不是显示页面。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onStart</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token string single-quoted-string">&#39;Hello World&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="从-ajax-处理程序返回字符串"><a href="#从-ajax-处理程序返回字符串" class="header-anchor">#</a> 从 AJAX 处理程序返回字符串</h4><p>从 AJAX 处理程序返回字符串将使用默认键 <code>result</code> 将字符串添加到响应集合中。请求的部分仍将包含在响应中。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onDoSomething</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token string single-quoted-string">&#39;Hello World&#39;</span><span class="token punctuation">;</span>
    <span class="token comment">// [&#39;result&#39; =&gt; &#39;Hello World&#39;]</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="从路由返回字符串"><a href="#从路由返回字符串" class="header-anchor">#</a> 从路由返回字符串</h4><p>从 <a href="./../services/router.html">路由定义</a> 返回字符串将与 CMS 方法相同，并将字符串显示为响应。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Route</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;/&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token string single-quoted-string">&#39;Hello World&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="创建自定义响应"><a href="#创建自定义响应" class="header-anchor">#</a> 创建自定义响应</h4><p>对于更健壮的解决方案，返回一个 <code>Response</code> 对象，提供各种用于构建 HTTP 响应的方法。我们将在本文中进一步探讨这个主题。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$contents</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Page not found&#39;</span><span class="token punctuation">;</span>
<span class="token variable">$statusCode</span> <span class="token operator">=</span> <span class="token number">404</span><span class="token punctuation">;</span>
<span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token variable">$contents</span><span class="token punctuation">,</span> <span class="token variable">$statusCode</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="将标题附加到响应"><a href="#将标题附加到响应" class="header-anchor">#</a> 将标题附加到响应</h3><p>请记住，大多数响应方法都是可链接的，允许流畅地构建响应。例如，您可以使用 <code>header</code> 方法将一系列标头添加到响应中，然后再将其发送回用户：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token variable">$content</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">header</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Content-Type&#39;</span><span class="token punctuation">,</span> <span class="token variable">$type</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">header</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;X-Header-One&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Header Value&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">header</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;X-Header-Two&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Header Value&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>一个实际的例子是返回一个 XML 响应</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token variable">$xmlString</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">header</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Content-Type&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;text/xml&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="将-cookie-附加到响应"><a href="#将-cookie-附加到响应" class="header-anchor">#</a> 将 Cookie 附加到响应</h3><p><code>withCookie</code> 方法允许您轻松地将 cookie 附加到响应中。例如，您可以使用 withCookie 方法生成一个 cookie 并将其附加到响应实例：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token variable">$content</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">withCookie</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;value&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><code>withCookie</code> 方法接受额外的可选参数，允许您进一步自定义 cookie 的属性</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token operator">-&gt;</span><span class="token function">withCookie</span><span class="token punctuation">(</span><span class="token variable">$name</span><span class="token punctuation">,</span> <span class="token variable">$value</span><span class="token punctuation">,</span> <span class="token variable">$minutes</span><span class="token punctuation">,</span> <span class="token variable">$path</span><span class="token punctuation">,</span> <span class="token variable">$domain</span><span class="token punctuation">,</span> <span class="token variable">$secure</span><span class="token punctuation">,</span> <span class="token variable">$httpOnly</span><span class="token punctuation">)</span>
</code></pre></div><h2 id="其他响应类型"><a href="#其他响应类型" class="header-anchor">#</a> 其他响应类型</h2><p><code>Response</code> 门面可用于方便地生成其他类型的响应实例。</p><h3 id="查看响应"><a href="#查看响应" class="header-anchor">#</a> 查看响应</h3><p>如果您需要访问 <code>Response</code> 类方法，但又想返回 <a href="#oc-views">视图</a> 作为响应内容，可以使用 <code>Response::view</code> 方法方便：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">view</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog::hello&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">header</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Content-Type&#39;</span><span class="token punctuation">,</span> <span class="token variable">$type</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="json-响应"><a href="#json-响应" class="header-anchor">#</a> JSON 响应</h3><p><code>json</code> 方法会自动将 <code>Content-Type</code> 标头设置为 application/json，并使用 <code>json_encode</code> PHP 函数将给定数组转换为 JSON：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">json</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Steve&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;state&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;CA&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>如果您想创建 JSONP 响应，除了 <code>setCallback</code> 之外，还可以使用 <code>json</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">json</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Steve&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;state&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;CA&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">setCallback</span><span class="token punctuation">(</span><span class="token class-name static-context">Input</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;callback&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="文件下载"><a href="#文件下载" class="header-anchor">#</a> 文件下载</h3><p><code>download</code> 方法可用于生成强制用户浏览器在给定路径下载文件的响应。 <code>download</code> 方法接受文件名作为该方法的第二个参数，这将确定下载文件的用户看到的文件名。最后，您可以将一组 HTTP 标头作为该方法的第三个参数传递：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">download</span><span class="token punctuation">(</span><span class="token variable">$pathToFile</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">download</span><span class="token punctuation">(</span><span class="token variable">$pathToFile</span><span class="token punctuation">,</span> <span class="token variable">$name</span><span class="token punctuation">,</span> <span class="token variable">$headers</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">download</span><span class="token punctuation">(</span><span class="token variable">$pathToFile</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">deleteFileAfterSend</span><span class="token punctuation">(</span><span class="token constant boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><blockquote><p><strong>注意</strong>: 管理文件下载的 Symfony HttpFoundation 要求正在下载的文件具有 ASCII 文件名。</p></blockquote><p><a id="oc-redirects"></a></p><h2 id="重定向"><a href="#重定向" class="header-anchor">#</a> 重定向</h2><p>定向响应通常是 <code>Illuminate\\Http\\RedirectResponse</code> 类的实例，并包含将用户重定向到另一个 URL 所需的正确标头。 生成 <code>RedirectResponse</code> 实例的最简单方法是使用 <code>Redirect</code> 门面上的 <code>to</code> 方法。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Redirect</span><span class="token operator">::</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;user/login&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="使用闪存数据返回重定向"><a href="#使用闪存数据返回重定向" class="header-anchor">#</a> 使用闪存数据返回重定向</h3><p>重定向到一个新的 URL 和 <a href="./../services/session.html">将闪存数据存到Session</a> 通常是同时完成的。 因此，为方便起见，您可以在单个方法链中创建一个 <code>RedirectResponse</code> 实例并将数据闪存到Session中：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Redirect</span><span class="token operator">::</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;user/login&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">with</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;message&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Login Failed&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><blockquote><p><strong>注意</strong>: 由于 <code>with</code> 方法将数据闪烁到Session中，您可以使用典型的 <code>Session::get</code> 方法检索数据。</p></blockquote><h4 id="重定向到上一个-url"><a href="#重定向到上一个-url" class="header-anchor">#</a> 重定向到上一个 URL</h4><p>您可能希望将用户重定向到他们以前的位置，例如，在提交表单之后。您可以使用 <code>back</code> 方法来做到这一点</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Redirect</span><span class="token operator">::</span><span class="token function">back</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">return</span> <span class="token class-name static-context">Redirect</span><span class="token operator">::</span><span class="token function">back</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">withInput</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="重定向到当前页面"><a href="#重定向到当前页面" class="header-anchor">#</a> 重定向到当前页面</h4><p>有时你想简单地刷新当前页面，你可以使用 <code>refresh</code> 方法来做到这一点：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Redirect</span><span class="token operator">::</span><span class="token function">refresh</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="响应宏"><a href="#响应宏" class="header-anchor">#</a> 响应宏</h2><p>如果您想定义一个可以在各种路由和控制器中重复使用的自定义响应，您可以使用 <code>Response::macro</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">macro</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;caps&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$value</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token function">strtoupper</span><span class="token punctuation">(</span><span class="token variable">$value</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><code>macro</code> 函数接受一个名字作为它的第一个参数，一个闭包作为它的第二个参数。在 <code>Response</code> 类上调用宏名称时，将执行宏的闭包：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">caps</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>您可以在 <a href="./../plugin/registration.html#oc-registration-methods">插件注册文件</a>.的 <code>boot</code> 方法中定义宏。或者，插件可以在插件目录中提供一个名为 <strong>init.php</strong> 的文件，您可以使用它来放置宏注册。</p><p><a id="oc-views"></a></p><h2 id="视图"><a href="#视图" class="header-anchor">#</a> 视图</h2><p>视图是存储基于系统的表示逻辑的好方法，例如 API 或端点使用的标记，或与 CMS 和后端区域共享的标记 <a href="./../services/mail.html">邮件服务</a> 也使用视图来提供默认模板内容。视图通常存储在插件的 <code>views</code> 目录中。</p><p>一个简单的视图可能看起来像这样：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token comment">&lt;!-- View stored in plugins/acme/blog/views/greeting.htm --&gt;</span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>html</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span>Hello, <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> name <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>html</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>视图也可以通过使用 <code>.php</code> 扩展名使用 PHP 模板进行解析：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">&lt;!-- View stored in plugins/acme/blog/views/greeting.php --&gt;</span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>html</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span>Hello, <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$name</span> <span class="token delimiter important">?&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>html</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>这个视图可以使用 <code>View::make</code> 方法返回给浏览器：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">View</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog::greeting&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Charlie&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>第一个参数是包含插件名称的&quot;路径提示&quot;，由两个冒号<code>::</code>分隔，后跟视图文件名。传递给 <code>View::make</code> 的第二个参数是一个数据数组，应该对视图可用。</p><blockquote><p><strong>注意</strong>: 路径提示区分大小写，插件名称应始终为小写。</p></blockquote><h4 id="将数据传递给视图"><a href="#将数据传递给视图" class="header-anchor">#</a> 将数据传递给视图</h4><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// 使用常规方法</span>
<span class="token variable">$view</span> <span class="token operator">=</span> <span class="token class-name static-context">View</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog::greeting&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">with</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Steve&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// 使用魔术方法</span>
<span class="token variable">$view</span> <span class="token operator">=</span> <span class="token class-name static-context">View</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog::greeting&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">withName</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;steve&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>在上面的示例中，变量 <code>name</code>可以从视图中访问，并且包含 <code>Steve</code>。如上所述，如果你想传递一个数据数组，你可以这样做作为传递给 <code>make</code> 方法的第二个参数：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$view</span> <span class="token operator">=</span> <span class="token class-name static-context">View</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog::greeting&#39;</span><span class="token punctuation">,</span> <span class="token variable">$data</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>也可以在所有视图之间共享一条数据：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">View</span><span class="token operator">::</span><span class="token function">share</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Steve&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="将子视图传递给视图"><a href="#将子视图传递给视图" class="header-anchor">#</a> 将子视图传递给视图</h4><p>有时您可能希望将一个视图传递给另一个视图。例如，给定一个存储在 <code>plugins/acme/blog/views/child/view.php</code> 的子视图，我们可以将它传递给另一个视图，如下所示：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$view</span> <span class="token operator">=</span> <span class="token class-name static-context">View</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog::greeting&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nest</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;child&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;acme.blog::child.view&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$view</span> <span class="token operator">=</span> <span class="token class-name static-context">View</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog::greeting&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nest</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;child&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;acme.blog::child.view&#39;</span><span class="token punctuation">,</span> <span class="token variable">$data</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>然后可以从父视图呈现子视图</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>html</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span>你好!<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
        <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> child<span class="token operator">|</span>raw <span class="token delimiter punctuation">}}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>html</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h4 id="判断视图是否存在"><a href="#判断视图是否存在" class="header-anchor">#</a> 判断视图是否存在</h4><p>如果需要检查视图是否存在，请使用 <code>View::exists</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">View</span><span class="token operator">::</span><span class="token function">exists</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog::mail.customer&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span>
</code></pre></div>`,83))])}const w=p(u,[["render",r]]);export{f as __pageData,w as default};
